#!/usr/bin/env node
/**
 * Copy the shell integration scripts into `dist/surfaces/shell-integration/`.
 *
 * `tsc` only emits JavaScript, so without this step the published gateway (and
 * the Tauri desktop bundle built from it) ships without the `.sh`/`.ps1`
 * integration scripts. That silently disabled OSC 633 shell integration,
 * which is what broke terminal prompt detection and command completion.
 *
 * Run as part of `npm run build`. The runtime also has an embedded fallback
 * (`src/surfaces/shell-integration-assets.ts`, generated by
 * `scripts/embed-shell-integration.mjs`), so a stale install still works — but
 * shipping the real files keeps them inspectable and lets `source`-based flows
 * pick them up directly.
 */
import { cpSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = join(here, "..");
const source = join(packageRoot, "src", "surfaces", "shell-integration");
const target = join(packageRoot, "dist", "surfaces", "shell-integration");

if (!existsSync(source)) {
  console.error(`shell integration source directory not found: ${source}`);
  process.exit(1);
}

mkdirSync(target, { recursive: true });
cpSync(source, target, { recursive: true });

console.log(`Copied shell integration scripts → ${target}`);
